<?php
namespace CGM\Core\Integrations\Gutenberg;use CGM\Core\Plugin;
final class QueryLoopBlock {
    public function __construct(private Plugin $core){}
    public function register():void{add_action('init',array($this,'block'),45);}
    public function block():void{register_block_type(CGM_CORE_PATH.'blocks/query-loop',array('render_callback'=>array($this,'render')));}
    public function render(array $attributes,string $content,\WP_Block $block):string{$mode=sanitize_key((string)($attributes['mode']??'saved'));$query='inline'===$mode?(array)($attributes['queryDefinition']??array()):sanitize_text_field((string)($attributes['queryId']??''));if(!$query)return is_admin()?'<div class="components-placeholder">'.esc_html__('Choose or build a CGM query.','cgm-core').'</div>':'';$ctx=array('post_id'=>get_the_ID(),'current_query_item'=>absint($block->context['postId']??0));$result=$this->core->queries()->run($query,$ctx);if('inline'!==$mode)$this->core->saved_queries()->record_usage($query,'gutenberg','block:cgm-core/query-loop');if(!$result->items)return !empty($attributes['showEmpty'])?'<p class="cgm-query-loop-empty">'.esc_html__('No results.','cgm-core').'</p>':'';$inner=$block->parsed_block['innerBlocks']??array();if(!$inner)return '';$originalPost=$GLOBALS['post']??null;$originalObject=$GLOBALS['cgm_core_query_object']??null;$html='<div class="wp-block-cgm-core-query-loop">';foreach($result->items as $item){$GLOBALS['cgm_core_query_object']=$item;if($item instanceof \WP_Post){$GLOBALS['post']=$item;setup_postdata($item);}$html.='<div class="cgm-query-loop-item">';foreach($inner as $parsed)$html.=render_block($parsed);$html.='</div>';}$html.='</div>';if($originalPost instanceof \WP_Post){$GLOBALS['post']=$originalPost;setup_postdata($originalPost);}else wp_reset_postdata();if(null===$originalObject)unset($GLOBALS['cgm_core_query_object']);else$GLOBALS['cgm_core_query_object']=$originalObject;return $html;}
}
